export const vittaUnits: VittaUnit[] = rawData.map((u) => ({
  ...u,
  valorStr: u.valorVenda.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
  valorFormatado: fmtCurrency(u.valorVenda),
}));

export function getVittaUnitsByBloco(bloco: string): VittaUnit[] {
  return vittaUnits.filter((u) => u.bloco === bloco);
}

export function getVittaStats() {
  const total = vittaUnits.length;
  const disponiveis = vittaUnits.filter((u) => u.status === "disponivel").length;
  const vendidos = vittaUnits.filter((u) => u.status === "vendido").length;
  const valorMin = Math.min(...vittaUnits.filter((u) => u.valorVenda > 0).map((u) => u.valorVenda));
  const valorMax = Math.max(...vittaUnits.filter((u) => u.valorVenda > 0).map((u) => u.valorVenda));
  return { total, disponiveis, vendidos, valorMin, valorMax };
}